import React, { useState } from 'react';

export default function StudentForm({ mode = 'add', initial = null, onCancel, onSubmit }){
  const [name, setName] = useState(initial ? initial.name : '');
  const [section, setSection] = useState(initial ? initial.section : '');
  const [marks, setMarks] = useState(initial ? initial.marks : '');
  const [grade, setGrade] = useState(initial ? initial.grade : '');

  const handleSubmit = (e) => {
    e.preventDefault();
    // Basic payload
    const payload = {
      name: name.trim(),
      section: section.trim(),
      marks: Number(marks),
      grade: grade.trim()
    };
    if(mode === 'edit' && initial && initial.id) payload.id = initial.id;
    onSubmit(payload);
  };

  return (
    <div>
      <h2>{mode === 'add' ? 'Add Student' : 'Edit Student'}</h2>
      <form onSubmit={handleSubmit} style={{maxWidth:480}}>
        <label style={{display:'block',marginBottom:8}}>
          Name<br/>
          <input value={name} onChange={e=>setName(e.target.value)} required style={{width:'100%',padding:8}} />
        </label>

        <label style={{display:'block',marginBottom:8}}>
          Section<br/>
          <input value={section} onChange={e=>setSection(e.target.value)} required style={{width:'100%',padding:8}} />
        </label>

        <label style={{display:'block',marginBottom:8}}>
          Marks<br/>
          <input type="number" value={marks} onChange={e=>setMarks(e.target.value)} required style={{width:'100%',padding:8}} />
        </label>

        <label style={{display:'block',marginBottom:8}}>
          Grade<br/>
          <input value={grade} onChange={e=>setGrade(e.target.value)} required style={{width:'100%',padding:8}} />
        </label>

        <div style={{marginTop:12}}>
          <button type="submit">{mode === 'add' ? 'Add' : 'Save'}</button>{' '}
          <button type="button" onClick={onCancel}>Cancel</button>
        </div>
      </form>
      <div style={{marginTop:10,color:'#666'}}>After submit, an alert will appear. Click "Load Students" to refresh data.</div>
    </div>
  );
}
